<?php require_once __DIR__.'/config/auth.php';require_admin();$id=(int)($_GET['id']??$_POST['id']??0);$s=db()->prepare('SELECT p.*,a.ref_number FROM payments p JOIN archives a ON a.id=p.archive_id WHERE p.id=?');$s->execute([$id]);$p=$s->fetch();if(!$p)exit('Payment not found.');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$amount=(float)($_POST['amount']??0);if(trim($_POST['sender_name']??'')===''||trim($_POST['sender_phone']??'')===''||$amount<=0){$err='Sender details and an amount greater than zero are required.';}else{$s=db()->prepare('UPDATE payments SET sender_name=?,sender_phone=?,amount=? WHERE id=?');$s->execute([trim($_POST['sender_name']),trim($_POST['sender_phone']),$amount,$id]);flash('success','Payment updated.');redirect('payments_list.php');}}$title='Edit Payment';require __DIR__.'/includes/header.php';?><h1>Edit payment</h1><div class="card"><p class="muted">Archive: <?=e($p['ref_number'])?></p><?php if(!empty($err)):?><div class="alert error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="grid grid-2"><div class="field"><label>Sender name</label><input name="sender_name" value="<?=e($_POST['sender_name']??$p['sender_name'])?>" required></div><div class="field"><label>Sender phone</label><input name="sender_phone" value="<?=e($_POST['sender_phone']??$p['sender_phone'])?>" required></div><div class="field"><label>Amount</label><input type="number" step="0.01" min="0.01" name="amount" value="<?=e($_POST['amount']??$p['amount'])?>" required></div></div><button class="btn">Save changes</button></form></div><?php require __DIR__.'/includes/footer.php';
